parameters.jsCode:
const FENCE = String.fromCharCode(96).repeat(3);
const j = $input.first().json;
let raw = "";
if (j.content && Array.isArray(j.content.parts)) { raw = j.content.parts.map(p => p.text || "").join(""); }
else if (typeof j.text === "string") { raw = j.text; }
else { raw = JSON.stringify(j); }
raw = raw.split(FENCE + "json").join("").split(FENCE).join("").trim();
let b = {};
try { b = JSON.parse(raw); } catch (e) { const s = raw.indexOf("{"); const t = raw.lastIndexOf("}"); try { b = JSON.parse(raw.slice(s, t + 1)); } catch (e2) { b = { caption: raw }; } }
const hashtags = Array.isArray(b.hashtags) ? b.hashtags : (b.hashtags ? String(b.hashtags).split(/[ ,]+/).filter(Boolean) : []);
const plan = Array.isArray(b.campaign_plan) ? b.campaign_plan.map((d, i) => ({ day: Number(d && d.day) || i + 1, post_type: String((d && d.post_type) || ""), idea: String((d && d.idea) || "") })) : [];
const brief = {
  chat_id: String($("Telegram Trigger").first().json.message.chat.id),
  language: b.language || "",
  offer: b.offer || "",
  caption: b.caption || "",
  hashtags,
  voiceover_script: b.voiceover_script || "",
  image_prompt: b.image_prompt || "",
  reel_prompt: b.reel_prompt || "",
  hook: b.hook || "",
  cta: b.cta || "",
  campaign_plan: plan,
  style: b.style || "",
};
return [{ json: brief }];

