        "sql": "INSERT INTO vaanireel_posts (chat_id, language, offer, caption, hashtags, image_url, audio_url, video_url, total_cost_usd, status) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, 'completed')",
